INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_pyf_111', (SELECT id FROM catalog.course WHERE public_id = 'python-foundations-automation'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-foundations-automation') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pyf-1-1' AND is_deleted = false LIMIT 1), 'values-text-truthiness-quiz', 'Text, numbers and truthiness', 'Predict what Python does with values that arrive as text, before you write the receipt script.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pyf_111'), 'The restock bot reads the quantity from the chat command "/restock mug 0". What does this code print?

qty = "0"
if qty:
    print(f"{qty=}, doubled: {qty * 2}")
else:
    print("nothing to restock")', 'single_choice'::question_type, 'qty is the one-character string "0", not the number 0. Only the empty string "" is falsy; any non-empty string, including "0", " " and "False", is truthy, so the if branch runs. In that branch qty * 2 repeats the text ("00") instead of doubling a number, and {qty=} prints the expression and the repr of its value, quotes included: qty=''0''. Convert first (int(qty)) and both the test and the arithmetic behave like numbers.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pyf_111') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('nothing to restock', false),
        ('qty=0, doubled: 0', false),
        ('qty=''0'', doubled: 00', true),
        ('TypeError: can''t multiply sequence by non-int of type ''str''', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pyf_111'), 'Which of these expressions raise an error? (Select all that apply.)', 'multiple_choice'::question_type, 'int() accepts surrounding whitespace, so int(" 42 ") is 42, but it does not accept a decimal point: int("12.5") raises ValueError: invalid literal for int() with base 10: ''12.5''. float() does not understand thousands separators, so float("1,050") raises ValueError too. "Total: " + 3 raises TypeError: can only concatenate str (not "int") to str, because + never converts a number to text for you; str(3) or an f-string does. f"{1050000:,}" is fine and gives ''1,050,000''.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pyf_111') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('int(" 42 ")', false),
        ('int("12.5")', true),
        ('"Total: " + 3', true),
        ('float("1,050")', true),
        ('f"{1050000:,}"', false)
    ) AS o(option_text, is_correct);

