VALUES ('chal_quiz_pyf_211', (SELECT id FROM catalog.course WHERE public_id = 'python-foundations-automation'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-foundations-automation') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pyf-2-1' AND is_deleted = false LIMIT 1), 'defaults-and-scope-quiz', 'Predict the output: defaults and scope', 'Read each snippet the way Python runs it: when are default values created, and which names are local?', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pyf_211'), 'What does this print?

def add_tag(tag, tags=[]):
    tags.append(tag)
    return tags

a = add_tag("gift")
b = add_tag("express", [])
c = add_tag("bulk")
print(a, b, c)', 'single_choice'::question_type, 'The default list is created once, when def runs, and every call that leaves out tags gets that same list. The first call appends "gift" to it and returns it, so a IS the default list. The second call passes its own new list, so b is [''express''] and the default is untouched. The third call uses the default again and appends "bulk" - and returns the same list object that a already points to. a and c are two names for one list, so both print [''gift'', ''bulk''].', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pyf_211') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('[''gift''] [''express''] [''bulk'']', false),
        ('[''gift''] [''express''] [''gift'', ''bulk'']', false),
        ('[''gift'', ''bulk''] [''express''] [''gift'', ''bulk'']', true),
        ('[''gift'', ''bulk''] [''gift'', ''express''] [''gift'', ''express'', ''bulk'']', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pyf_211'), 'The module starts with:

synced = 0
failed = []

def a():
    print(synced)

def b():
    synced += 1

def c():
    print(synced)
    synced = 5

def d():
    failed.append("LM-1001")

def e():
    global synced
    synced += 1

Which of these functions raise UnboundLocalError when called? (Select all that apply.)', 'multiple_choice'::question_type, 'Python decides which names are local when it compiles the function: any name that is ASSIGNED anywhere in the body (=, +=, a for target...) is local in the whole body. `synced += 1` reads the local synced before it has a value, and in the print-then-assign version the later `synced = 5` makes synced local for the print too - both raise UnboundLocalError. A function that only reads synced sees the global. `failed.append(...)` does not assign to the name failed, it changes the list the name points to, so it works. With `global synced`, the assignment goes to the module variable - it works, but hidden module state like this is a smell.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pyf_211') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('a() - only reads synced', false),
        ('b() - synced += 1', true),
        ('c() - print(synced), then synced = 5', true),
        ('d() - failed.append("LM-1001")', false),
        ('e() - global synced, then synced += 1', false)
    ) AS o(option_text, is_correct);

