-- challenge chal_quiz_pyf_321 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_pyf_321', (SELECT id FROM catalog.course WHERE public_id = 'python-foundations-automation'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-foundations-automation') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pyf-3-2' AND is_deleted = false LIMIT 1), 'normalize-and-dedupe-quiz', 'Equal after cleaning? Which row survives?', 'Predict what normalization and a dict-based dedupe really do before you write the cleaning function.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pyf_321'), 'import unicodedata

nfc = "Hà Nội"                              # typed on a laptop (composed)
nfd = unicodedata.normalize("NFD", nfc)    # the same city from the mobile app
nbsp = "Hà\u00a0Nội"                       # pasted from a web page

Which expressions are True? (Select all that apply.)', 'multiple_choice'::question_type, 'NFC recombines the base letters and combining marks of nfd, so the first comparison is True. casefold() changes case only: nfd keeps its separate combining marks, so the casefolded strings still differ. strip() removes whitespace at the ends only, and the non-breaking space is in the middle, so nbsp.strip() is unchanged. split() with no argument splits on any whitespace, including the non-breaking space, and " ".join(...) puts one normal space back, which gives exactly nfc. Normalization never removes accents: the casefolded city is "hà nội", not "ha noi" - that spelling needs an alias table.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pyf_321') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('unicodedata.normalize("NFC", nfd) == nfc', true),
        ('nfd.casefold() == nfc.casefold()', false),
        ('nbsp.strip() == nfc', false),
        ('" ".join(nbsp.split()) == nfc', true),
        ('unicodedata.normalize("NFC", nfc).casefold() == "ha noi"', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pyf_321'), 'rows = [
    {"email": "lan@lotus.vn", "city": "Huế"},
    {"email": " Lan@Lotus.vn", "city": "Đà Nẵng"},
    {"email": "minh@lotus.vn", "city": "Huế"},
]
customers = {}
for row in rows:
    customers[row["email"].strip().casefold()] = row["city"]
print(list(customers.items()))

What does it print?', 'single_choice'::question_type, 'Both Lan rows have the same key "lan@lotus.vn" after strip() and casefold(). Assigning to a key that already exists replaces its value, so the second row''s city wins: this loop keeps the LAST row for each customer. The key itself keeps its original position - a dict is ordered by when each key was first inserted, and replacing a value does not move it. To keep the first row instead, skip the row when the key is already in the dict (if key in customers: continue).', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pyf_321') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('[(''lan@lotus.vn'', ''Huế''), (''minh@lotus.vn'', ''Huế'')]', false),
        ('[(''lan@lotus.vn'', ''Đà Nẵng''), (''minh@lotus.vn'', ''Huế'')]', true),
        ('[(''minh@lotus.vn'', ''Huế''), (''lan@lotus.vn'', ''Đà Nẵng'')]', false),
        ('[(''lan@lotus.vn'', ''Huế''), (''lan@lotus.vn'', ''Đà Nẵng''), (''minh@lotus.vn'', ''Huế'')]', false)
    ) AS o(option_text, is_correct);

