INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_fix_pyf_411', (SELECT id FROM catalog.course WHERE public_id = 'python-foundations-automation'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-foundations-automation') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pyf-4-1' AND is_deleted = false LIMIT 1), 'fix-price-import-exception-group', 'Make the nightly price update report every bad row', 'import_prices(rows, catalog) applies the supplier''s price sheet to the catalog. Today a bare except: pass hides unreadable rows (and quietly re-applies the previous row''s price instead), the first non-positive price stops the whole run, and the original KeyError or ValueError is never attached to the error. Fix it: check every row, apply only the good ones, turn each bad row into a PriceError with its row number and the original error as __cause__ (raise ... from err), and raise one ExceptionGroup("<bad> of <total> rows invalid", errors) at the end. The runner at the bottom (do not change it) catches the group with except* PriceError and prints the report the job sends: updated count, the group message, every error with its row, message and cause type, and the catalog after the run.', 'open', 'medium'::difficulty_question, 'fix_bug', 20, true, false)
