-- challenge chal_quiz_pyf_421 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_pyf_421', (SELECT id FROM catalog.course WHERE public_id = 'python-foundations-automation'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-foundations-automation') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pyf-4-2' AND is_deleted = false LIMIT 1), 'dataclass-and-type-hint-behaviour-quiz', 'What does a dataclass really do?', 'Predict what generated dataclass methods and type hints do at runtime before you rely on them in a script.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pyf_421'), 'from dataclasses import dataclass

@dataclass(frozen=True)
class Sku:
    code: str
    qty: int = 0

a = Sku("MUG", 2)
b = Sku("MUG", 2)

Which statements are true? (Select all that apply.)', 'multiple_choice'::question_type, '@dataclass generates __eq__, which compares the fields in order, so a == b is True even though a and b are two different objects (a is b is False). frozen=True makes the generated __setattr__ raise dataclasses.FrozenInstanceError: cannot assign to field ''qty''. A dataclass with eq=True (the default) and frozen=True also gets a __hash__ built from its fields, so a and b have the same hash and the set {a, b} holds one element. A mutable default such as tags: list[str] = [] is rejected when the class is defined: ValueError: mutable default <class ''list''> for field tags is not allowed: use default_factory. The instances never get the chance to share it.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pyf_421') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('a == b is True', true),
        ('a is b is True', false),
        ('a.qty = 3 raises dataclasses.FrozenInstanceError', true),
        ('len({a, b}) == 1', true),
        ('Adding the field tags: list[str] = [] to Sku works, but every Sku then shares one list', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pyf_421'), 'Python 3.14, no type checker is run:

@dataclass
class LogEntry:
    status: int
    duration_ms: int

entry = LogEntry(status="504", duration_ms=1830)
print(entry.status >= 500)

What happens?', 'single_choice'::question_type, 'Type hints are not checked or converted at runtime: the generated __init__ stores whatever it is given, so entry.status is the string "504". The bug only shows up later, where the value is used: comparing a str with an int raises TypeError: ''>='' not supported between instances of ''str'' and ''int''. A type checker such as mypy or pyright would flag the LogEntry(status="504", ...) call before the script runs; at runtime, convert explicitly with int(...) where the text comes in.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pyf_421') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('LogEntry(...) raises TypeError because "504" is not an int', false),
        ('The dataclass converts "504" to 504, so it prints True', false),
        ('The object is created with status "504"; the comparison raises TypeError', true),
        ('It prints False, because a str is never >= an int', false)
    ) AS o(option_text, is_correct);

